using System;
using System.Collections;
using System.IO;
using UnityEngine;

// First process saves a real live checkpoint; second process loads it through startup restoration.
public sealed class AmbientPedestrianProbeRunner : MonoBehaviour {
 public DriveSession session;
 string error="";
 string Artifact(string name){return Path.GetFullPath(Path.Combine(Application.dataPath,"../../..","artifacts",name));}
 static void Check(bool okay,string message){if(!okay)throw new Exception("AMBIENT_PEDESTRIAN_PROBE "+message);}
 IEnumerator Start(){yield return new WaitForSecondsRealtime(1);var args=Environment.GetCommandLineArgs();bool captureOnly=Array.IndexOf(args,"-ambientCaptureOnly")>=0,reload=Array.IndexOf(args,"-ambientPedestrianReloadTest")>=0;IEnumerator gate=captureOnly?CaptureOnlyGate():reload?ReloadGate():FirstGate();while(true){object next;try{if(!gate.MoveNext())break;next=gate.Current;}catch(Exception ex){error=ex.ToString();Debug.LogException(ex);break;}yield return next;}string stage=captureOnly?"capture":reload?"reload":"save";string report=Artifact(captureOnly?"ambient-pedestrian-capture.txt":reload?"ambient-pedestrian-reload.txt":"ambient-pedestrian-test.txt");Directory.CreateDirectory(Path.GetDirectoryName(report));File.WriteAllText(report,"success="+string.IsNullOrEmpty(error)+"\n"+(string.IsNullOrEmpty(error)?"placement="+session.ambientPedestrians.PlacementReport+"\n":"error="+error+"\n"));Debug.Log("AMBIENT_PEDESTRIAN_PROBE_"+(string.IsNullOrEmpty(error)?"OK":"FAILED")+" stage="+stage+" report="+report);Application.Quit(string.IsNullOrEmpty(error)?0:1);}
 IEnumerator CaptureOnlyGate(){Check(session&&session.ambientPedestrians,"capture runtime absent");var crossing=session.ambientPedestrians.actors.Find(a=>a.route.crossing&&a.route.hub=="J5076_2580");Check(crossing!=null,"capture crossing absent");crossing.ForceCrossingForProbe(.45f);yield return CaptureVisual(crossing);Check(File.Exists(Artifact("ambient-pedestrians.png")),"capture image missing");Debug.Log("AMBIENT_GATE_CAPTURE_OK route="+crossing.route.id+" image="+Artifact("ambient-pedestrians.png"));}
 IEnumerator FirstGate(){
  Check(session&&session.ambientPedestrians,"runtime absent");Check(session.business.SavePath==Artifact("ambient-pedestrian-test.json"),"save isolation path");var system=session.ambientPedestrians;Check(system.actors.Count<=12&&system.actors.Count>0,"budget or zero safe routes");
  foreach(var actor in system.actors){if(actor.route.crossing)Check(system.placement.IsSafe(actor.route,0)&&system.placement.IsSafe(actor.route,1),"crossing endpoints "+actor.route.id);else{Check(actor.route.Length>=19.99f&&actor.route.Length<=40.01f,"walk length "+actor.route.id);for(int n=0;n<=32;n++)Check(system.placement.IsSafe(actor.route,n/32f),"walk footing "+actor.route.id+" at "+n);}}
  var crossing=system.actors.Find(a=>a.route.crossing&&a.route.hub=="J5076_2580")??system.actors.Find(a=>a.route.crossing);Check(crossing!=null,"no validated crossing");
  foreach(var actor in system.actors)foreach(var passenger in session.jobs.people)Check(actor.gameObject!=passenger&&actor.transform.parent!=passenger.transform,"passenger array separation");
  foreach(var car in session.traffic.cars)if(car){car.respawn=false;car.Recycle();}
  Check(!session.business.preparing&&!session.paused&&Time.timeScale>0,"test campaign unexpectedly paused");session.traffic.manualClock=true;float green=-1,greenEnd=-1;for(float t=0;t<200;t+=.1f){session.traffic.manualTime=t;bool lit=session.traffic.PedestrianGreen(crossing.route.junction,crossing.route.axis,crossing.route.sign);if(lit&&green<0)green=t;if(!lit&&green>=0){greenEnd=t;break;}}Check(green>=0&&greenEnd>green+9,"pedestrian green phase missing");
  var malformed=system.Capture();var bad=Array.Find(malformed.actors,a=>a.id==crossing.route.id);bad.progress=.5f;bad.crossing=false;bool rejected=false;try{system.Validate(malformed);}catch(ArgumentException){rejected=true;}Check(rejected,"idle midroad checkpoint accepted");bad.crossing=true;bad.rest=1;rejected=false;try{system.Validate(malformed);}catch(ArgumentException){rejected=true;}Check(rejected,"active crossing with rest accepted");
  var completedState=new RightPracticeState(6);completedState.Advance(5,true);Check(!ScenarioChoiceSituation.MayReleaseCompletedObservation(completedState,4.5f),"PS09 crossing released after score completion");completedState.Advance(1,true);Check(ScenarioChoiceSituation.MayReleaseCompletedObservation(completedState,6f),"PS09 arrived crossing not released");
  var longCrossing=system.actors.Find(a=>a.route.crossing&&a.route.Length>40);Check(longCrossing!=null,"long crossing missing");var taxiPosition=session.taxi.transform.position;var taxiRotation=session.taxi.transform.rotation;session.taxi.SetSpawn(longCrossing.route.b+Vector3.up*.65f,taxiRotation);session.taxi.ResetTaxi();Physics.SyncTransforms();Check(Vector3.Distance(session.taxi.transform.position,(longCrossing.route.a+longCrossing.route.b)*.5f)>14,"taxi is not at far end");Check(!system.MayStartCrossing(longCrossing),"taxi body at long crossing far end did not block entry");session.taxi.SetSpawn(taxiPosition,taxiRotation);session.taxi.ResetTaxi();Physics.SyncTransforms();
  crossing.ResetSafe();crossing.state.rest=0;session.traffic.manualTime=green-1;yield return null;Check(!crossing.Crossing,"red entry");
  session.traffic.manualTime=greenEnd-1;Check(session.traffic.PedestrianGreen(crossing.route.junction,crossing.route.axis,crossing.route.sign)&&session.traffic.PedestrianGreenRemaining(crossing.route.junction,crossing.route.axis,crossing.route.sign)<=2,"late green timing setup");yield return null;Check(!crossing.Crossing,"last two seconds entry");
  session.traffic.manualTime=green+1;yield return null;Check(crossing.Crossing,"green entry with clear vehicles");
  crossing.ForceCrossingForProbe(.4f);var j=crossing.route.junction;var incoming=session.traffic.AxisDirection(j,crossing.route.axis)*crossing.route.sign;var nearRoute=new TrafficRoute();nearRoute.SetPoints(new[]{j.center-incoming*(j.StopDistance(crossing.route.axis,crossing.route.sign)+8),j.center+incoming*25});var carProbe=new GameObject("pedestrian route yield probe").AddComponent<TrafficCar>();carProbe.enabled=false;carProbe.route=nearRoute;carProbe.distance=8.5f;float gap=system.OccupiedCrossingGap(carProbe,35);Check(!float.IsInfinity(gap)&&gap<20,"occupied route yields after stop line");var unrelated=new TrafficRoute();var shift=TrafficSystem.Right(incoming)*35;unrelated.SetPoints(new[]{nearRoute.start+shift,nearRoute.end+shift});carProbe.route=unrelated;carProbe.distance=0;Check(float.IsInfinity(system.OccupiedCrossingGap(carProbe,35)),"unrelated route remains clear");Destroy(carProbe.gameObject);
  var movingCar=new GameObject("pedestrian braking probe").AddComponent<TrafficCar>();movingCar.Initialize(session.traffic,nearRoute,8.5f,97);movingCar.respawn=false;movingCar.speed=4;session.traffic.cars.Add(movingCar);float carBefore=movingCar.distance;yield return new WaitForFixedUpdate();Check(movingCar.waitingForObstacle&&movingCar.distance<=carBefore+.01f,"actual car failed to stop at occupied crossing");session.traffic.cars.Remove(movingCar);Destroy(movingCar.gameObject);
  session.traffic.manualTime=green+11;float before=crossing.state.progress;yield return null;Check(crossing.Crossing&&crossing.state.progress>before,"red transition preserves crossing progress");
  session.traffic.manualTime=green+1;crossing.ForceCrossingForProbe(.97f);Time.timeScale=8;yield return new WaitForSecondsRealtime(.5f);Time.timeScale=1;Check(!crossing.Crossing&&crossing.state.reverse&&crossing.state.greenConsumed&&crossing.state.rest<=0,"same-green crossing completed and rest expired");yield return new WaitForSecondsRealtime(.3f);Check(!crossing.Crossing,"same-green reentry after rest");
  crossing.ForceCrossingForProbe(.97f);session.traffic.manualTime=green+11;Time.timeScale=8;yield return new WaitForSecondsRealtime(.5f);Time.timeScale=1;Check(!crossing.Crossing&&!crossing.state.reverse,"crossing finishes on red");
  var crossingDirection=crossing.route.b-crossing.route.a;var beside=new Vector3(-crossingDirection.z,0,crossingDirection.x).normalized;session.taxi.SetSpawn(crossing.transform.position+beside*20+Vector3.up*.65f,taxiRotation);session.taxi.ResetTaxi();crossing.state.rest=0;crossing.state.greenConsumed=false;session.traffic.manualTime=green+1;Check(system.MayStartCrossing(crossing),"deferred entry probe lacks a clear crossing");crossing.state.deferredReveal=true;system.ReconcileVisibility();yield return null;yield return null;Check(!crossing.Crossing&&!crossing.VisualActive&&crossing.Capture().deferredReveal,"nearby deferred actor entered or reappeared");session.taxi.SetSpawn(taxiPosition,taxiRotation);session.taxi.ResetTaxi();crossing.state.deferredReveal=false;system.ReconcileVisibility();
  crossing.ForceCrossingForProbe(.45f);session.traffic.manualTime=green+11;yield return CaptureVisual(crossing);Check(File.Exists(Artifact("ambient-pedestrians.png")),"actual actor screenshot missing");crossing.ForceCrossingForProbe(.45f);
  Check(session.business.SaveCheckpoint(),"real checkpoint write");var saved=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(session.business.SavePath));Check(saved!=null&&saved.hasLive&&saved.live!=null&&saved.live.ambientPedestrians!=null,"live pedestrian payload written");var state=Array.Find(saved.live.ambientPedestrians.actors,a=>a.id==crossing.route.id);Check(state!=null&&state.crossing&&Mathf.Abs(state.progress-.45f)<.12f,"mid crossing progress saved");Debug.Log("AMBIENT_GATE_SAVE_OK route="+crossing.route.id+" progress="+state.progress+" actors="+system.actors.Count+" screenshot="+Artifact("ambient-pedestrians.png"));
 }
 IEnumerator CaptureVisual(AmbientPedestrian crossing){
  string screenshot=Artifact("ambient-pedestrians.png");var follow=session.drivingCamera;var camera=follow.GetComponent<Camera>();var oldPosition=camera.transform.position;var oldRotation=camera.transform.rotation;float oldFov=camera.fieldOfView,oldScale=Time.timeScale;bool oldFollow=follow.enabled,oldPaused=session.paused,oldJobs=session.jobs.enabled;
  var passenger=session.jobs.people.Length>0?session.jobs.people[0]:null;Check(passenger!=null,"capture passenger absent");var oldPassengerPosition=passenger.transform.position;bool oldPassengerActive=passenger.activeSelf;
  session.paused=true;Time.timeScale=0;follow.enabled=false;session.jobs.enabled=false;crossing.ReconcileVisibility();
  try{
   if(File.Exists(screenshot))File.Delete(screenshot);
   Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.7f);Screen.SetResolution(1920,1080,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.7f);
   passenger.transform.position=crossing.route.a;passenger.SetActive(true);
   var actorFocus=crossing.transform.position+Vector3.up;var passengerFocus=passenger.transform.position+Vector3.up;var center=(actorFocus+passengerFocus)*.5f;var roadSide=crossing.route.junction.center-center;roadSide.y=0;if(roadSide.sqrMagnitude<1){var along=crossing.route.b-crossing.route.a;roadSide=new Vector3(-along.z,0,along.x);}camera.transform.position=center+roadSide.normalized*12+Vector3.up*5;camera.transform.LookAt(center);camera.fieldOfView=50;
   var actorView=camera.WorldToViewportPoint(actorFocus);var passengerView=camera.WorldToViewportPoint(passengerFocus);Check(actorView.z>0&&passengerView.z>0&&actorView.x>.1f&&actorView.x<.9f&&passengerView.x>.1f&&passengerView.x<.9f,"capture subjects outside camera");
   yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(screenshot);yield return new WaitForSecondsRealtime(.8f);Check(File.Exists(screenshot),"actual actor screenshot missing");
  }finally{
   passenger.transform.position=oldPassengerPosition;passenger.SetActive(oldPassengerActive);camera.transform.SetPositionAndRotation(oldPosition,oldRotation);camera.fieldOfView=oldFov;follow.enabled=oldFollow;session.jobs.enabled=oldJobs;session.paused=oldPaused;Time.timeScale=oldScale;
  }
 }
 IEnumerator ReloadGate(){Check(session&&session.ambientPedestrians,"runtime absent");Check(session.business.SavePath==Artifact("ambient-pedestrian-test.json"),"reload save isolation");Check(!session.business.ResumeBlocked,"checkpoint rejected");var saved=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(session.business.SavePath));Check(saved!=null&&saved.live!=null&&saved.live.ambientPedestrians!=null,"saved live snapshot unavailable");var expected=Array.Find(saved.live.ambientPedestrians.actors,a=>a.crossing);Check(expected!=null,"saved crossing occupant unavailable");var actor=session.ambientPedestrians.At(expected.id);Check(actor!=null&&actor.Crossing,"occupied crossing not restored before motion");Check(Mathf.Abs(actor.state.progress-expected.progress)<.04f,"restored crossing progress");Check(session.ambientPedestrians.actors.Count==saved.live.ambientPedestrians.actors.Length,"duplicate actors after restore");var j=actor.route.junction;var incoming=session.traffic.AxisDirection(j,actor.route.axis)*actor.route.sign;var route=new TrafficRoute();route.SetPoints(new[]{j.center-incoming*(j.StopDistance(actor.route.axis,actor.route.sign)+8),j.center+incoming*25});var car=new GameObject("pedestrian reload yield probe").AddComponent<TrafficCar>();car.enabled=false;car.route=route;car.distance=8.5f;Check(!float.IsInfinity(session.ambientPedestrians.OccupiedCrossingGap(car,35)),"restored occupancy not yielding");Destroy(car.gameObject);session.traffic.manualClock=true;session.traffic.manualTime=0;session.paused=false;Time.timeScale=1;float progress=actor.state.progress;yield return new WaitForSecondsRealtime(.25f);Check(actor.Crossing&&actor.state.progress>progress,"restored crossing does not continue on red");Debug.Log("AMBIENT_GATE_RELOAD_OK route="+expected.id+" saved="+expected.progress+" resumed="+actor.state.progress+" occupants=1");}
}
